-- AI module (orbit_backend.ai): settings, consent, engine probes, jobs, usage ledger,
-- output cache, session facets and generated artifacts. Idempotent; applied on open.
CREATE TABLE IF NOT EXISTS ai_setting (key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)), updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS ai_consent (engine TEXT NOT NULL, data_class TEXT NOT NULL CHECK(data_class IN ('summary','snippets','rules','raw')), granted INTEGER NOT NULL CHECK(granted IN (0,1)), changed_at INTEGER NOT NULL, PRIMARY KEY(engine,data_class)) STRICT;
CREATE TABLE IF NOT EXISTS ai_consent_log (id INTEGER PRIMARY KEY, engine TEXT NOT NULL, data_class TEXT NOT NULL, granted INTEGER NOT NULL, at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS ai_engine (engine TEXT PRIMARY KEY, info TEXT NOT NULL CHECK(json_valid(info)), checked_at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS ai_job (job_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, engine TEXT NOT NULL, slot TEXT NOT NULL, template TEXT NOT NULL DEFAULT 'v1', goal TEXT, goal_source TEXT, request TEXT NOT NULL CHECK(json_valid(request)), preview_digest TEXT, status TEXT NOT NULL CHECK(status IN ('queued','running','ok','partial','fallback','failed','cancelled')), stage TEXT, progress_n INTEGER NOT NULL DEFAULT 0, progress_total INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', log TEXT NOT NULL DEFAULT '[]', result TEXT, error TEXT, cached INTEGER NOT NULL DEFAULT 0, artifact_id TEXT, created_at INTEGER NOT NULL, started_at INTEGER, finished_at INTEGER) STRICT;
CREATE INDEX IF NOT EXISTS ai_job_created ON ai_job(created_at DESC);
CREATE TABLE IF NOT EXISTS ai_usage (id INTEGER PRIMARY KEY, job_id TEXT NOT NULL, task_id TEXT NOT NULL, engine TEXT NOT NULL, model_id TEXT, input_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, output_tokens INTEGER, est_input_tokens INTEGER, cost_usd REAL, cost_source TEXT NOT NULL CHECK(cost_source IN ('reported','price_table','unknown')), latency_ms INTEGER, status TEXT NOT NULL, ts INTEGER NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS ai_usage_ts ON ai_usage(ts);
CREATE TABLE IF NOT EXISTS ai_cache (input_digest TEXT PRIMARY KEY, task_id TEXT NOT NULL, prompt_version TEXT NOT NULL, schema_version TEXT NOT NULL, output TEXT NOT NULL CHECK(json_valid(output)), model_id TEXT, created_at INTEGER NOT NULL, expires_at INTEGER, hits INTEGER NOT NULL DEFAULT 0, last_hit_at INTEGER) STRICT;
CREATE TABLE IF NOT EXISTS ai_facet (session_uid TEXT NOT NULL, prompt_version TEXT NOT NULL, schema_version TEXT NOT NULL, content_hash TEXT NOT NULL, model_id TEXT, status TEXT NOT NULL CHECK(status IN ('ok','failed','skipped','stale')), json TEXT CHECK(json IS NULL OR json_valid(json)), job_id TEXT, created_at INTEGER NOT NULL, PRIMARY KEY(session_uid,prompt_version,schema_version)) STRICT;
CREATE TABLE IF NOT EXISTS ai_artifact (artifact_id TEXT PRIMARY KEY, job_id TEXT, kind TEXT NOT NULL CHECK(kind IN ('rule','glue','hook','skill','subagent','command','workflow')), template_id TEXT NOT NULL, name TEXT NOT NULL, title TEXT, goal TEXT, goal_source TEXT, slots TEXT NOT NULL CHECK(json_valid(slots)), payload TEXT NOT NULL CHECK(json_valid(payload)), files TEXT NOT NULL CHECK(json_valid(files)), checks TEXT NOT NULL CHECK(json_valid(checks)), evidence TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(evidence)), personalized INTEGER NOT NULL CHECK(personalized IN (0,1)), content_hash TEXT NOT NULL, preview_digest TEXT, status TEXT NOT NULL CHECK(status IN ('draft','blocked','installed','reverted','archived')), install_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ai_artifact_hash ON ai_artifact(content_hash);
CREATE INDEX IF NOT EXISTS ai_artifact_created ON ai_artifact(created_at DESC);
